
const monateMap={"Januar":"01","Februar":"02","März":"03","April":"04","Mai":"05","Juni":"06","Juli":"07","August":"08","September":"09","Oktober":"10","November":"11","Dezember":"12","January":"01","February":"02","March":"03","May":"05","June":"06","July":"07","October":"10","December":"12"};const ICS_ZEILENENDE="\r\n";function icsHeader(){return["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//MCH Singen//Terminkalender//DE","CALSCALE:GREGORIAN","METHOD:PUBLISH","",].join(ICS_ZEILENENDE);}
function icsText(wert){return String(wert??"").replace(/\\/g,"\\\\").replace(/;/g,"\\;").replace(/,/g,"\\,").replace(/\r?\n/g,"\\n");}
function icsZeitstempel(){return new Date().toISOString().replace(/[-:]/g,"").replace(/\.\d{3}/,"");}
function icsKennung(bestandteile){const sauber=bestandteile.join("-").replace(/[^A-Za-z0-9\-]/g,"");return`${sauber}@mch-singen.de`;}
function icsEndzeit(jahr,monat,tag,startHHMM,dauerStunden){const stunde=parseInt(startHHMM.slice(0,2),10);const minute=parseInt(startHHMM.slice(2,4),10);const ende=new Date(Date.UTC(+jahr,+monat-1,+tag,stunde+dauerStunden,minute));const zz=n=>String(n).padStart(2,'0');return`${ende.getUTCFullYear()}${zz(ende.getUTCMonth() + 1)}${zz(ende.getUTCDate())}`
+`T${zz(ende.getUTCHours())}${zz(ende.getUTCMinutes())}00`;}
function icsTermin({kennung,titel,start,ende,ort,beschreibung,url}){const zeilen=["BEGIN:VEVENT",`UID:${kennung}`,`DTSTAMP:${icsZeitstempel()}`,`DTSTART:${start}`,`DTEND:${ende}`,`SUMMARY:${icsText(titel)}`,];if(ort)zeilen.push(`LOCATION:${icsText(ort)}`);if(beschreibung)zeilen.push(`DESCRIPTION:${icsText(beschreibung)}`);if(url)zeilen.push(`URL:${url}`);zeilen.push("END:VEVENT","");return zeilen.join(ICS_ZEILENENDE);}
async function ladeUndGeneriereICS(zielGruppe){try{const res=await fetch('../data/trainingstermine2026.txt');const data=await res.text();let ics=icsHeader();data.split('\n').forEach(zeile=>{if(!zeile.trim())return;const p=zeile.split(';');if(p.length<5)return;const tag=p[0].trim().padStart(2,'0');const monat=monateMap[p[1].trim()];const jahr=p[2].trim();const start=p[3].trim().split('-')[0].trim().replace(':','');const gruppe=p[4].trim();if(gruppe==zielGruppe||gruppe=="3"){const endeRoh=(p[3].split('-')[1]??'').trim().replace(':','');ics+=icsTermin({kennung:icsKennung(['training',jahr,monat,tag,start,gruppe]),titel:`MCH Training Gruppe ${gruppe}`,start:`${jahr}${monat}${tag}T${start}00`,ende:endeRoh?`${jahr}${monat}${tag}T${endeRoh}00`:icsEndzeit(jahr,monat,tag,start,2),ort:'Münchriedstraße 10, Singen',});}});ics+="END:VCALENDAR";downloadFile(ics,`MCH_Training_Gruppe_${zielGruppe}.ics`);}catch{alert("Fehler beim Laden der Trainingstermine.");}}
async function ladeRenntermineICS(){try{const res=await fetch('../data/timer.txt');const data=await res.text();let ics=icsHeader();data.split('\n').forEach(zeile=>{if(!zeile.trim())return;const p=zeile.split(';');if(p.length<4)return;const tag=p[0].trim().padStart(2,'0');const monat=monateMap[p[1].trim()];const jahr=p[2].trim();const zeit=p[3].trim().replace(':','');const verein=p[4]?.trim()??"";const ort=p[5]?.trim()??"Unbekannt";const mapsLink=p[6]?.trim()??"";ics+=icsTermin({kennung:icsKennung(['kart',jahr,monat,tag,verein,ort]),titel:`Rennen beim ${verein} ${ort}`,start:`${jahr}${monat}${tag}T${zeit}00`,ende:icsEndzeit(jahr,monat,tag,zeit,8),ort:ort,beschreibung:mapsLink?`Google Maps: ${mapsLink}`:'',url:mapsLink,});});ics+="END:VCALENDAR";downloadFile(ics,"MCH_Kart_Renntermine.ics");}catch{alert("Fehler beim Laden der Kart-Renntermine.");}}
async function ladeTrialRenntermineICS(){try{const res=await fetch('../data/timer_trial.txt');const data=await res.text();let ics=icsHeader();data.split('\n').forEach(zeile=>{if(!zeile.trim())return;const p=zeile.split(';');if(p.length<4)return;const tag=p[0].trim().padStart(2,'0');const monat=monateMap[p[1].trim()];const jahr=p[2].trim();const zeit=p[3].trim().replace(':','');const verein=p[4]?.trim()??"";const ort=p[5]?.trim()??"Unbekannt";const mapsLink=p[6]?.trim()??"";ics+=icsTermin({kennung:icsKennung(['trial',jahr,monat,tag,verein,ort]),titel:`Trial-Lauf ${verein} ${ort}`,start:`${jahr}${monat}${tag}T${zeit}00`,ende:icsEndzeit(jahr,monat,tag,zeit,8),ort:ort,beschreibung:mapsLink?`Google Maps: ${mapsLink}`:'',url:mapsLink,});});ics+="END:VCALENDAR";downloadFile(ics,"MCH_Trial_Renntermine.ics");}catch{alert("Fehler beim Laden der Trial-Renntermine.");}}
function downloadFile(content,fileName){const blob=new Blob([content],{type:'text/calendar;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=fileName;link.click();URL.revokeObjectURL(link.href);}